def point_in_convex_hull(point, vertices):
    point = np.array(point)
    n = len(vertices)
    for i in range(n):
        j = (i + 1) % n
        p1, p2 = np.array(vertices[i]), np.array(vertices[j])
        cross = np.cross(p2 - point, p1 - point)
        if cross < 0:  # Clockwise
            return True
    return False

